def fetch_all(client):
    result = []
    cursor = "START"
    while True:
        page = client.fetch_page(cursor)
        for item in page["items"]:
            if item.get("deleted") is True:
                continue
            result.append(item)
        cursor = page["next"]
        if cursor is None:
            return result

