class _Client:
    def __init__(self, pages):
        self.pages = pages
        self.calls = []
    def fetch_page(self, cursor):
        self.calls.append(cursor)
        return self.pages[cursor]

def check(candidate):
    pages = {
        "START": {"items": [{"id": 1}, {"id": 2, "deleted": True}], "next": "c2"},
        "c2": {"items": [], "next": "c3"},
        "c3": {"items": [{"id": 3, "deleted": False}, {"id": 4}], "next": None},
    }
    c = _Client(pages)
    assert candidate(c) == [{"id": 1}, {"id": 3, "deleted": False}, {"id": 4}]
    assert c.calls == ["START", "c2", "c3"]
    c2 = _Client({"START": {"items": [{"id": 9}], "next": None}})
    assert candidate(c2) == [{"id": 9}]
    assert c2.calls == ["START"]
